from heapq import heappush, heappop
from typing import List

def min_time_to_stage_N(N: int, A: List[int], B: List[int], X: List[int]) -> int:
    min_time = [float('inf')] * N
    min_time[0] = 0
    pq = [(0, 0)]  # (time, stage)

    while pq:
        current_time, stage = heappop(pq)

        if stage == N - 1:
            return current_time

        # Proceed to stage i+1
        if stage + 1 < N:
            next_time = current_time + A[stage]
            if next_time < min_time[stage + 1]:
                min_time[stage + 1] = next_time
                heappush(pq, (next_time, stage + 1))

        # Jump to stage X[i]
        if stage < len(B):
            jump_stage = X[stage] - 1
            if jump_stage < N:
                next_time = current_time + B[stage]
                if next_time < min_time[jump_stage]:
                    min_time[jump_stage] = next_time
                    heappush(pq, (next_time, jump_stage))

    return min_time[N - 1]
